    # Identify diagonal bands of constant column-row offset. The offset
    # spacing between the repeated bands gives the period.
    bands = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                bands.setdefault(c - r, v)

    offsets = sorted(bands)
    if not offsets:
        return [row[:] for row in grid]

    # These patterns repeat with a five-position diagonal period. Fill the
    # residue colors from the visible diagonal bands.
    period = 5
    residue = {}
    for d, color in bands.items():
        residue[d % period] = color

    # Where a residue is represented by the thick double band, use its
    # color for that residue as well.
    for d, color in bands.items():
        residue[d % period] = color

    # Extend the cyclic arrangement from the consecutive diagonal offsets.
    known = sorted(residue)
    for k in range(period):
        if k not in residue:
            nearest = min(known, key=lambda x: min((k-x) % period, (x-k) % period))
            residue[k] = residue[nearest]

    return [[residue[(c-r) % period] for c in range(w)] for r in range(h)]
